/** Disposable checkpoint playthrough. Uses real audio acknowledgements and normal client inputs. */
public final class RescueFinaleVisualCheck {
    private static volatile boolean ready;private static volatile String serverState="";private static volatile String blocker="";
    private static volatile String clientAudio="";
    private static int ticks,webSample;private static BlockPos webCenter,sourceDoor;private static java.util.UUID catId,webSession;
    private static final java.util.Map<String,long[]> fps=new java.util.TreeMap<>();
    private static final java.util.UUID[] ghosts=new java.util.UUID[3];private static final java.util.Set<String> shots=new java.util.HashSet<>();
    private static final java.util.Set<String> savedCheckpoints=new java.util.HashSet<>();
    /** This checkpoint skips boss setup, but still needs its real prior venue for Cat retirement. */
    private static void preparePriorVenue(net.minecraft.server.level.ServerPlayer p,VisitData.Scene s){if(Boolean.getBoolean("coraline.rescueFinaleNoTheatre"))return;if(!ShowSiteData.get(p.server).owner(s.owner).getBoolean("TheatreBuilt")){if(!TheatreSite.prepare(p,s))throw new IllegalStateException("Checkpoint lacks the actual prior theatre venue required by Cat departure");System.out.println("RESCUE_FINALE_PRIOR_VENUE_PREPARED normal production theatre builder; NOT boss/venue playthrough acceptance");}}
    /** Ordinary disk saves only. Never changes story gates, recordings, actors or inputs. */
    private static void saveVerifiedCheckpoint(Minecraft mc){var server=mc.getSingleplayerServer();server.execute(()->{var p=server.getPlayerList().getPlayers().get(0);var s=OtherMotherLoop.scene(p);String current=RescueChapter.phase(s).name();if(java.util.Set.of("FAREWELL_A","EYES_CLOSE","FAREWELL_C").contains(current)&&savedCheckpoints.add(current)){server.saveEverything(false,true,true);System.out.println("RESCUE_FINALE_CHECKPOINT_SAVED phase="+current+" original SavedData/entities/owner preserved; safe recording recovery still required");}});}
    public static void resume(Minecraft mc){mc.getSingleplayerServer().execute(()->{
        var p=mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);var s=OtherMotherLoop.scene(p);if(s==null||!s.owner.equals(p.getUUID())||!RescueChapter.started(s))throw new IllegalStateException("Disposable resume has no original owner continuation");var n=RescueChapter.data(s);var door=DoorData.get(p.server).doors.get(s.door);if(door==null||!s.owner.equals(door.owner)||ParentAccess.family(p.server,s.owner)==null)throw new IllegalStateException("Disposable resume lost canonical source door/family");sourceDoor=door.pos;webCenter=RescueWebSite.center(p,s);var original=s.loop.story.getCompound("CanonicalStoryCat");if(!original.hasUUID("Entity"))throw new IllegalStateException("No original Cat receipt on resume");catId=original.getUUID("Entity");var old=FirstEscapeStory.data(s);for(int i=0;i<3;i++){if(!old.hasUUID("Ghost"+i))throw new IllegalStateException("Original prison child receipt missing on resume");ghosts[i]=old.getUUID("Ghost"+i);}if(!n.getBoolean("CatHit")||!n.getBoolean("KeyRecovered")||!n.getBoolean("BeldamBlind"))throw new IllegalStateException("Cannot resume without the actual prior Cat/key/blind checkpoints");if(Boolean.getBoolean("coraline.rescueFinaleNoTheatre")){if(n.getBoolean("FarewellCatDeparted"))throw new IllegalStateException("Cat departed before no-theatre checkpoint injection");ShowSiteData.get(p.server).owner(s.owner).remove("TheatreBuilt");System.out.println("RESCUE_FINALE_EXPLICIT_NO_THEATRE_CHECKPOINT: theatre flag cleared in disposable copy; NOT a natural route");}System.out.println("RESCUE_FINALE_NATIVE_RESUME loaded original saved identities and completed A-Q checkpoints; NOT an uninterrupted playthrough");ready=true;
    });}
    public static void stage(Minecraft mc){mc.getSingleplayerServer().execute(()->{
        var p=mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);var s=OtherMotherLoop.scene(p);var old=FirstEscapeStory.data(s);
        old.putBoolean("InternalTransfer",true);p.stopRiding();old.remove("InternalTransfer");p.setForcedPose(null);p.setPose(Pose.STANDING);ShowPlayback.stop(p,s);
        FirstEscapeScene.preparePrison(p,s);for(int i=0;i<3;i++){var ghost=FirstEscapeScene.ensure(p,s,"Ghost"+i,CinematicPropEntity.GHOST_CHILD,i,p.serverLevel(),Vec3.atBottomCenterOf(FirstEscapeScene.prison(s)).add(i-1,0,0));if(ghost==null)throw new IllegalStateException("Original prison child fixture unavailable");ghosts[i]=ghost.getUUID();ghost.setInvisible(true);}
        old.putString("Phase","ESCAPE_COMPLETE");old.putBoolean("Complete",true);old.putBoolean("Grabbed",false);
        var root=ParentRescueStory.data(s);root.put("Scenery",old.copy());root.putBoolean("Started",true);root.putBoolean("Complete",true);root.putBoolean("KeyTaken",true);root.putBoolean("KeySwallowed",true);root.putBoolean("WardrobeBlocking",true);
        if(!ParentRescueStory.grantKey(p,s)||!StoryItemCustody.capture(p,s,"Key",stack->ParentRescueStory.key(stack,s)))throw new IllegalStateException("Original key fixture could not enter real custody");s.loop.story.putString("LittleDoorKeyHolder","EVIL_OTHER_MOTHER");
        var stone=new ItemStack(ModItems.SEEING_STONE.get());stone.getOrCreateTag().putUUID("StoryOwner",s.owner);stone.getTag().putUUID("StoryDoor",s.door);p.getInventory().add(stone);
        for(int i=0;i<3;i++){RescueEyes.eye(s,i).putBoolean("Defeated",true);RescueEyes.eye(s,i).putBoolean("Discovered",true);if(!RescueEyes.claim(p,s,i))throw new IllegalStateException("Authentic eye fixture failed");}p.getInventory().selected=8;p.connection.send(new net.minecraft.network.protocol.game.ClientboundSetCarriedItemPacket(8));
        var door=DoorData.get(p.server).doors.get(s.door);sourceDoor=door.pos;var real=p.server.overworld();for(int x=-12;x<=12;x++)for(int z=-12;z<=12;z++){var cell=sourceDoor.offset(x,-1,z);real.getChunkAt(cell);real.setBlock(cell,Blocks.STONE_BRICKS.defaultBlockState(),2);for(int y=0;y<4;y++)real.setBlock(cell.above(y+1),Blocks.AIR.defaultBlockState(),2);}real.setBlock(sourceDoor,ModBlocks.TINY_DOOR.get().defaultBlockState(),2);
        var family=new FamilyData.Family();family.owner=s.owner;family.storyMissing=true;family.bed=sourceDoor.east(9);family.chest=sourceDoor.east(10);FamilyData.get(p.server).families.put(family.id,family);
        var mom=ModEntities.MOM.get().create(real);var dad=ModEntities.DAD.get().create(real);mom.familyId=dad.familyId=family.id;mom.setPos(Vec3.atBottomCenterOf(sourceDoor.west(5)));dad.setPos(Vec3.atBottomCenterOf(sourceDoor.east(5)));real.addFreshEntity(mom);real.addFreshEntity(dad);family.mom=mom.getUUID();family.dad=dad.getUUID();family.momPos=mom.blockPosition();family.dadPos=dad.blockPosition();FamilyData.get(p.server).setDirty();
        var mother=ParentRescueStory.mother(p,s);if(mother==null)throw new IllegalStateException("Saved Other Mother missing");mother.stopRiding();mother.setInvisible(false);mother.setPos(Vec3.atBottomCenterOf(FirstEscapeScene.room(s).west(3)));
        var cat=ShowActors.acquire(p,s,"cat",p.serverLevel(),Vec3.atBottomCenterOf(FirstEscapeScene.room(s)).add(-2,1.4,5));if(cat==null)throw new IllegalStateException("Canonical Cat unavailable");catId=cat.getUUID();
        p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.setInvulnerable(false);p.setNoGravity(false);p.teleportTo(p.serverLevel(),FirstEscapeScene.room(s).getX()+.5,FirstEscapeScene.room(s).getY()+.1,FirstEscapeScene.room(s).getZ()+.5,90,0);RescueChapter.data(s).putBoolean("Started",true);webCenter=RescueWebSite.center(p,s);RescueChapter.go(p,s,RescueChapter.Phase.FINAL_A);ready=true;
    });}
    public static void tick(Minecraft mc){if(!ready||mc.player==null)return;ticks++;String phase=RescueClient.phase();stopKeys(mc);
        if(ticks%20==0&&java.util.Set.of("FAREWELL_A","EYES_CLOSE","FAREWELL_C").contains(phase))saveVerifiedCheckpoint(mc);
        if(ticks==1)mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);preparePriorVenue(p,OtherMotherLoop.scene(p));});
        if(ticks%100==0){clientAudio=audioState(mc);System.out.println("RESCUE_FINALE_CLIENT_AUDIO "+clientAudio);}
        if(ticks%20==0&&!phase.isEmpty()){int current=mc.getFps();if(current>0){var sample=fps.computeIfAbsent(phase,key->new long[]{0,0,Long.MAX_VALUE,0});sample[0]++;sample[1]+=current;sample[2]=Math.min(sample[2],current);sample[3]=Math.max(sample[3],current);System.out.println("RESCUE_FINALE_FPS phase="+phase+" reported="+current);}}
        if(ticks%100==0)mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);var s=OtherMotherLoop.scene(p);var n=RescueChapter.data(s);var audio=ShowPlayback.data(s);serverState=RescueChapter.phase(s).name();blocker=n.getString("Blocker");System.out.println("RESCUE_FINALE_PROGRESS phase="+serverState+" ticks="+n.getInt("Ticks")+" blocker="+blocker+" at="+p.position()+" retries="+n.getInt("RetryCount")+" lastRetry="+n.getString("LastRetryReason")+" crouch="+p.isCrouching()+" moved="+n.getDouble("LastWebMoved")+" step="+n.getDouble("LastWebStep")+" packets="+n.getInt("LastWebPackets")+" sticky="+n.getBoolean("LastWebSticky")+" landed="+n.getBoolean("LastWebLanded")+" noiseAge="+n.getInt("NoiseAge")+" waypoint="+webSample+" audio="+audio.getString("Sound")+" started="+audio.getBoolean("Started")+" ended="+audio.getBoolean("Ended")+" endWait="+audio.getInt("EndWait"));});
        if(java.util.Set.of("SHOW_EYES","HIDING_CHOICE","FIGHT_CHOICE","DOOR_STRUGGLE").contains(phase)){if(mc.screen!=null&&ticks%4==0)mc.screen.mouseClicked(mc.getWindow().getGuiScaledWidth()/2.,mc.getWindow().getGuiScaledHeight()/2.+10,0);return;}
        if(phase.equals("CAT_THROW")){var cat=mc.level.getEntity((int)RescueClient.value("Cat"));if(!RescueClient.flag("CatHeld")){if(cat!=null){aim(mc,cat.getEyePosition());if(mc.player.distanceToSqr(cat)>10)mc.options.keyUp.setDown(true);else if(ticks%4==0)mc.gameMode.interact(mc.player,cat,InteractionHand.MAIN_HAND);}}else{var mother=mc.level.getEntity(RescueClient.mother());if(mother!=null)aim(mc,BeldamFinale.facePoint(mother));mc.options.keyAttack.setDown(ticks%8<4);}}
        else if(phase.equals("WEB_STEALTH")){var session=RescueClient.inputSession();if(!java.util.Objects.equals(session,webSession)){webSession=session;webSample=0;}mc.options.keyShift.setDown(true);var point=RescueWebLayout.point(1,Math.min(1,webSample/(double)RescueWebLayout.SAMPLES));var target=new Vec3(webCenter.getX()+point.x(),webCenter.getY()+point.y(),webCenter.getZ()+point.z());if(mc.player.position().subtract(target).horizontalDistanceSqr()<.05&&webSample<RescueWebLayout.SAMPLES)webSample++;aim(mc,new Vec3(target.x,mc.player.getEyeY()-.2,target.z));mc.options.keyUp.setDown(true);}
        else if(phase.equals("TUNNEL_CHASE")){mc.player.setYRot(-90);mc.player.setXRot(12);mc.options.keyUp.setDown(true);}
        else if(phase.equals("LOCK_DOOR")){aim(mc,sourceDoor.getCenter());if(ticks%4==0)mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,new BlockHitResult(sourceDoor.getCenter(),Direction.UP,sourceDoor,false));}
        else if(phase.equals("CAT_NOTICE")){var cat=mc.level.getEntity((int)RescueClient.value("Cat"));if(cat!=null){aim(mc,cat.getEyePosition());if(mc.player.distanceToSqr(cat)>12)mc.options.keyUp.setDown(true);}}
        else if(phase.startsWith("FINAL_")&&!phase.equals("FINAL_O")){var mother=mc.level.getEntity(RescueClient.mother());if(mother!=null)aim(mc,BeldamFinale.facePoint(mother));}
        if(java.util.Set.of("FINAL_A","FINAL_N","FINAL_P","WEB_STEALTH","TUNNEL_CHASE","REUNION_A","ORBS","FAREWELL_C").contains(phase)&&RescueClient.time()>(phase.equals("ORBS")?80:25)&&shots.add(phase))shot(mc,phase.toLowerCase());
        if(phase.equals("FINAL_N")&&RescueClient.time()>RescueClient.duration()-75&&shots.add("blind"))shot(mc,"beldam_blind");
        if(phase.equals("FAREWELL_C")&&RescueClient.time()>260&&shots.add("sad"))shot(mc,"ghosts_sad");
        if(phase.equals("FAREWELL_C")&&RescueClient.time()>RescueClient.duration()-50&&shots.add("blur"))shot(mc,"farewell_blur");
        if(phase.equals("COMPLETE")||serverState.equals("COMPLETE")||shots.contains("complete")){
            if(shots.add("complete"))shot(mc,"complete");
            if(Boolean.getBoolean("coraline.rescueFinaleNoTheatre")&&mc.player.position().distanceToSqr(sourceDoor.offset(24,0,24).getCenter())<40*40){aim(mc,sourceDoor.offset(24,0,24).getCenter());mc.player.setYRot(mc.player.getYRot()+180);mc.player.setXRot(0);mc.options.keyUp.setDown(true);}else for(var farewellCat:mc.level.entitiesForRendering())if(farewellCat.getUUID().equals(catId)){aim(mc,farewellCat.getEyePosition());mc.player.setYRot(mc.player.getYRot()+180);mc.player.setXRot(0);break;}
            if(ticks%20==0)mc.getSingleplayerServer().execute(()->{
                var p=mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);var s=OtherMotherLoop.scene(p);var n=RescueChapter.data(s);
                if(!n.getBoolean("FarewellCatDeparted")){var cat=ShowActors.actor(p,s,"cat");System.out.println("RESCUE_FINALE_CAT_PENDING loaded="+(cat!=null)+" visible="+(cat!=null&&ShowActors.visibleToAnyone(cat,p))+" cat="+(cat==null?"unavailable":cat.position())+" theatre="+ShowSiteData.get(p.server).owner(s.owner).getBoolean("TheatreBuilt"));return;}
                try{verify(mc);}catch(RuntimeException|AssertionError failure){System.out.println("RESCUE_FINALE_NATIVE_FAILED "+failure.getMessage());mc.execute(mc::stop);throw failure;}
                finally{ready=false;}
            });
        }
    }
    private static void verify(Minecraft mc){var p=mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);var s=OtherMotherLoop.scene(p);var n=RescueChapter.data(s);var family=ParentAccess.family(p.server,s.owner);var vision=n.getCompound("VisionReturn");int keys=0;for(var item:p.getInventory().items)if(ParentRescueStory.key(item,s))keys+=item.getCount();
        double returnDistance=p.position().distanceToSqr(new Vec3(vision.getDouble("X"),vision.getDouble("Y"),vision.getDouble("Z")));
        if(!n.getBoolean("PermanentlySealed")||!n.getBoolean("ParentsReturned")||!n.getBoolean("FarewellComplete")||!n.getBoolean("BeldamBlind")||!n.getBoolean("HandSevered")||!n.getBoolean("FarewellCatDeparted")||!ParentRescueStory.data(s).getCompound("Custody").getCompound("Stone").getBoolean("Destroyed")||!RescueEyes.ledger(s).getBoolean("Released")||keys!=1||family==null||!family.rescued||family.storyMissing||p.isInvulnerable()||p.isNoGravity()||p.getForcedPose()!=null||!Boolean.getBoolean("coraline.rescueFinaleResume")&&returnDistance>1e-9)throw new IllegalStateException("Final checkpoint invariants failed: keys="+keys+" family="+(family!=null)+" rescued="+(family!=null&&family.rescued)+" missing="+(family!=null&&family.storyMissing)+" invulnerable="+p.isInvulnerable()+" noGravity="+p.isNoGravity()+" forcedPose="+p.getForcedPose()+" returnDistanceSquared="+returnDistance+" state="+n);
        for(int i=0;i<3;i++)if(!FirstEscapeStory.data(s).getUUID("Ghost"+i).equals(ghosts[i]))throw new IllegalStateException("Original ghost UUID changed");if(!s.loop.story.getCompound("CanonicalStoryCat").getUUID("Entity").equals(catId))throw new IllegalStateException("Canonical Cat replaced");
        if(Boolean.getBoolean("coraline.rescueFinaleNoTheatre")&&!s.loop.story.getCompound("CanonicalStoryCat").getString("Dimension").equals(DoorData.get(p.server).doors.get(s.door).dimension))throw new IllegalStateException("No-theatre checkpoint did not retire Cat in the source dimension");
        fps.forEach((phase,sample)->System.out.println("RESCUE_FINALE_FPS_SUMMARY phase="+phase+" samples="+sample[0]+" mean="+(sample[1]/(double)sample[0])+" min="+sample[2]+" max="+sample[3]+"; sampled Minecraft reported FPS, not frame-time percentiles"));System.out.println("RESCUE_FINALE_NATIVE_COMPLETE "+(Boolean.getBoolean("coraline.rescueFinaleResume")?"resumed saved checkpoint, actual remaining originals, original identities and final invariants; NOT fresh A-Q/web/crawl or uninterrupted acceptance":"real acknowledged originals, manual choices/Cat throw, continuous client web/crawl, real-parent reunion and original-child farewell checkpoint playthrough"));mc.execute(mc::stop);
    }
    private static void aim(Minecraft mc,Vec3 at){var d=at.subtract(mc.player.getEyePosition());mc.player.setYRot((float)Math.toDegrees(Math.atan2(-d.x,d.z)));mc.player.setXRot((float)-Math.toDegrees(Math.atan2(d.y,d.horizontalDistance())));}
    private static void stopKeys(Minecraft mc){mc.options.keyUp.setDown(false);mc.options.keyShift.setDown(false);mc.options.keyAttack.setDown(false);}
    /** Read-only QA diagnostics; never sends or manufactures a playback signal. */
    private static String audioState(Minecraft mc){try{var field=com.coraline.client.VisitAudioClient.class.getDeclaredField("voice");field.setAccessible(true);var raw=field.get(null);if(!(raw instanceof net.minecraft.client.resources.sounds.SoundInstance sound))return "none";String result=sound.getLocation()+" class="+raw.getClass().getSimpleName()+" mixerActive="+mc.getSoundManager().isActive(sound);if(raw.getClass().getSimpleName().equals("StoryRun")){var type=raw.getClass();var cursor=type.getDeclaredField("segment");cursor.setAccessible(true);int segment=cursor.getInt(raw);var streamField=type.getDeclaredField("stream");streamField.setAccessible(true);var stream=streamField.get(raw);var seconds=type.getDeclaredMethod("seconds");seconds.setAccessible(true);result+=" segment="+segment+" seconds="+seconds.invoke(raw);if(stream instanceof com.coraline.client.audio.ContinuousAudioStream decoded)result+=" begin="+decoded.startSeconds(segment)+" end="+decoded.endSeconds(segment);}return result;}catch(ReflectiveOperationException failure){return "diagnostic unavailable: "+failure.getClass().getSimpleName();}}
    private static void shot(Minecraft mc,String name){try{var folder=java.nio.file.Path.of("screenshots","rescue_finale_qa");java.nio.file.Files.createDirectories(folder);try(var image=net.minecraft.client.Screenshot.takeScreenshot(mc.getMainRenderTarget())){image.writeToFile(folder.resolve(name+".png"));}}catch(Exception failure){throw new RuntimeException(failure);}}
    private RescueFinaleVisualCheck(){}
}
